"""Self-contained browser console. Credentials stay in this page's memory."""
PAGE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>iTOPAZ Agent · Control room</title>
<style nonce="__NONCE__">
:root{color-scheme:light;--ink:#172631;--muted:#657780;--border:#dce4e7;--paper:#fff;--accent:#df5b28;--green:#16775c}*{box-sizing:border-box}body{margin:0;background:#f3f6f7;color:var(--ink);font:15px/1.6 system-ui,sans-serif}button,input,textarea{font:inherit}button{cursor:pointer;border:1px solid var(--border);border-radius:9px;background:white;padding:10px 16px;color:var(--ink);font-weight:600}button.primary{background:var(--ink);border-color:var(--ink);color:white}button:disabled{opacity:.5;cursor:wait}input,textarea{width:100%;padding:11px 13px;border:1px solid var(--border);border-radius:8px;background:#fff;color:var(--ink)}input:focus,textarea:focus,button:focus-visible{outline:3px solid #df5b2850;outline-offset:2px}label{display:block;font-size:13px;font-weight:600;margin-bottom:5px}header{background:#172631;color:white}.top{max-width:1180px;margin:auto;padding:22px 28px;display:flex;justify-content:space-between;align-items:center;gap:16px}.brand{font-size:20px;font-weight:750;letter-spacing:-.6px}.brand span{color:#ff9867}.eyebrow{font-size:11px;letter-spacing:2px;text-transform:uppercase;color:var(--muted);font-weight:700}.top .eyebrow{color:#b7c5cc}.pill{font-size:12px;padding:5px 11px;border-radius:30px;background:#30444f;color:#d5e7ef}.layout{max-width:1180px;margin:0 auto;padding:32px 28px 50px}.intro{display:flex;justify-content:space-between;gap:30px;align-items:center;margin-bottom:24px}h1{font-size:35px;line-height:1.2;letter-spacing:-1.2px;margin:7px 0 10px}h2{font-size:18px;margin:0 0 6px;letter-spacing:-.3px}h3{font-size:15px;margin:0 0 5px}p{margin:0 0 14px}.muted{color:var(--muted)}.tag{color:var(--green);background:#e4f2ec;border:1px solid #c3dfd2;font-size:12px;padding:7px 12px;border-radius:30px;white-space:nowrap}.connect{display:grid;grid-template-columns:1fr auto auto;gap:12px;align-items:end;background:white;border:1px solid var(--border);padding:18px 22px;border-radius:12px;margin-bottom:20px}.hint{font-size:12px;color:var(--muted);margin-top:5px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:15px;margin-bottom:24px}.card{background:var(--paper);border:1px solid var(--border);border-radius:12px;padding:22px;min-width:0}.status{display:flex;align-items:center;gap:7px;color:var(--muted);font-size:13px}.dot{width:8px;height:8px;border-radius:50%;background:#99a8b1}.dot.good{background:var(--green)}.dot.bad{background:#c44343}.two{display:grid;grid-template-columns:1.5fr 1fr;gap:20px}.tabs{display:flex;gap:6px;padding-bottom:16px;border-bottom:1px solid var(--border);margin-bottom:20px}.tab{border:0;background:transparent;color:var(--muted)}.tab[aria-selected=true]{background:#f1f4f5;color:var(--ink)}.actions{display:flex;gap:10px;align-items:center;margin-top:12px}.output{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.7 system-ui,sans-serif;background:#f6f8f9;padding:18px;border-radius:9px;max-height:420px;overflow:auto;margin-top:18px}.output:empty{display:none}.routine{list-style:none;padding:0;margin:18px 0 0}.routine li{display:flex;gap:12px;padding:13px 0;border-top:1px solid var(--border)}.number{font-size:11px;line-height:25px;min-width:25px;height:25px;border-radius:50%;text-align:center;background:#eef2f4;color:var(--muted)}.routine p{font-size:13px;color:var(--muted);margin:0}.note{font-size:13px;color:var(--muted);padding:16px 0 0}.capabilities{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:20px}.capabilities .card p{font-size:13px;color:var(--muted);margin:0}footer{font-size:12px;color:var(--muted);display:flex;justify-content:space-between;gap:15px;margin-top:25px}code{font:12px/1.6 ui-monospace,monospace;background:#eef2f4;padding:2px 5px;border-radius:4px}.hidden{display:none}[role=alert]{color:#a43424;font-size:13px}.top a{color:#cad8df;text-decoration:none;font-size:13px}@media(max-width:760px){.layout{padding:24px 16px}.top{padding:18px 16px}.intro{align-items:flex-start;flex-direction:column;gap:12px}h1{font-size:29px}.connect{grid-template-columns:1fr auto}.connect .key{grid-column:1/-1}.grid,.two,.capabilities{grid-template-columns:1fr}.grid .card{padding:16px}footer{flex-direction:column}}
</style></head><body>
<header><div class="top"><div><div class="brand">i<span>TOPAZ</span> Agent</div><div class="eyebrow">AllCargo · Control room</div></div><div class="pill">DEV EKS / Windows master</div></div></header>
<main class="layout"><div class="intro"><div><div class="eyebrow">Your operations workspace</div><h1>Know what’s running.<br>Decide what changes.</h1><p class="muted">Check services, ask your knowledge base, and plan the next infrastructure action.</p></div><span class="tag">Approval required for every change</span></div>
<section class="connect" aria-label="Connect to the agent"><div class="key"><label for="token">Master access key</label><input id="token" type="password" autocomplete="off" placeholder="Enter your master access key"><div class="hint">Kept in this tab’s memory. Cleared when you disconnect or close the page.</div></div><button id="connect" class="primary">Connect</button><button id="disconnect">Disconnect</button><div id="error" role="alert" aria-live="polite"></div></section>
<section class="grid" aria-label="Service health"><div class="card"><div class="eyebrow">01 / Controller</div><h2>iTOPAZ Agent</h2><div class="status"><span class="dot" id="agent-dot"></span><span id="agent-state">Connect to check</span></div></div><div class="card"><div class="eyebrow">02 / Knowledge</div><h2>Topaz Knowledge</h2><div class="status"><span class="dot" id="knowledge-dot"></span><span id="knowledge-state">Connect to check</span></div></div><div class="card"><div class="eyebrow">03 / Infrastructure</div><h2>AWS Dashboard</h2><div class="status"><span class="dot" id="dashboard-dot"></span><span id="dashboard-state">Connect to check</span></div></div></section>
<section class="two"><div class="card"><div class="tabs" role="tablist" aria-label="Agent tools"><button class="tab" id="chat-tab" role="tab" aria-controls="chat-panel" aria-selected="true">Ask Topaz</button><button class="tab" id="search-tab" role="tab" aria-controls="search-panel" aria-selected="false">Search knowledge</button><button class="tab" id="inventory-tab" role="tab" aria-controls="inventory-panel" aria-selected="false">AWS inventory</button></div>
<div id="chat-panel" role="tabpanel" aria-labelledby="chat-tab"><h2>A clearer view of your infrastructure</h2><p class="muted">Ask about environments, incidents, or a resource change. Proposed changes need separate approval.</p><label for="question">Your question</label><textarea id="question" rows="3" maxlength="8000" placeholder="What needs attention in the DEV cluster today?"></textarea><div class="actions"><button id="ask" class="primary" disabled>Ask Topaz</button><span class="hint">Uses the connected knowledge chatbot</span></div></div>
<div id="search-panel" class="hidden" role="tabpanel" aria-labelledby="search-tab"><h2>Find the operational context</h2><p class="muted">Search the curated knowledge available to this agent.</p><label for="query">Search terms</label><input id="query" maxlength="500" placeholder="DEV cluster, deployment, troubleshooting…"><div class="actions"><button id="search" class="primary" disabled>Search</button></div></div>
<div id="inventory-panel" class="hidden" role="tabpanel" aria-labelledby="inventory-tab"><h2>Read the latest AWS inventory</h2><p class="muted">View the Dashboard’s cached account and resource data. Refreshing this view does not change resources.</p><button id="inventory" class="primary" disabled>Load inventory</button></div><div id="output" class="output" role="status" aria-live="polite"></div></div>
<aside class="card"><div class="eyebrow">Daily routine / run manually</div><h2>Start with these four checks</h2><ol class="routine"><li><span class="number">01</span><div><h3>Check service health</h3><p>Connect here and confirm the controller, Knowledge, and Dashboard respond.</p></div></li><li><span class="number">02</span><div><h3>Review incidents and deployments</h3><p>Ask Topaz for known issues and investigate failed jobs or restarted pods.</p></div></li><li><span class="number">03</span><div><h3>Review AWS capacity</h3><p>Load inventory and check running EC2, RDS, and EKS resources against today’s needs.</p></div></li><li><span class="number">04</span><div><h3>Approve only the changes you need</h3><p>Review the exact account, region, resource, and change from the Windows master.</p></div></li></ol><p class="note">These are suggested checks. No daily scheduler or automatic infrastructure changes are enabled.</p></aside></section>
<section class="capabilities" aria-label="Agent capabilities"><div class="card"><div class="eyebrow">Investigate</div><h3>Knowledge &amp; diagnostics</h3><p>Search runbooks and ask the chatbot for context. Worker commands and diagnostics use the existing operation lock.</p></div><div class="card"><div class="eyebrow">Coordinate</div><h3>SCM &amp; two workers</h3><p>The Windows master coordinates worker 1 and worker 2. Git changes are reviewed; Jenkins deploys each service.</p></div><div class="card"><div class="eyebrow">Control</div><h3>Explicit AWS actions</h3><p>Start, stop, tag, or scale supported resources through the authenticated Dashboard. Use <code>--dashboard-action</code> on the master and confirm each change.</p></div></section>
<footer><span>iTOPAZ Agent · Python runtime · DEV environment</span><span id="checked">Health checked on demand</span></footer></main>
<script nonce="__NONCE__">
(()=>{'use strict';let token='',connected=false;const el=id=>document.getElementById(id);const actionButtons=['ask','search','inventory'];function state(name,text,good){el(name+'-state').textContent=text;el(name+'-dot').className='dot'+(good===true?' good':good===false?' bad':'')}function error(text){el('error').textContent=text}function disconnect(){token='';connected=false;el('token').value='';actionButtons.forEach(id=>el(id).disabled=true);['agent','knowledge','dashboard'].forEach(id=>state(id,'Disconnected',null));el('output').textContent='';error('')}async function api(path,payload){if(!token)throw new Error('Connect with your master access key first.');const response=await fetch('/agentx/api/'+path,{method:payload?'POST':'GET',headers:{Authorization:'Bearer '+token,...(payload?{'Content-Type':'application/json'}:{})},body:payload?JSON.stringify(payload):undefined,cache:'no-store',credentials:'omit',redirect:'error'});const data=await response.json();if(!response.ok){if(response.status===401){disconnect();throw new Error('Access key rejected. Reconnect with the correct master key.')}throw new Error(data.error||'The request failed. Try again after checking service health.')}return data}async function run(id,work){const button=el(id);button.disabled=true;error('');try{await work()}catch(err){error(err.message)}finally{button.disabled=actionButtons.includes(id)?!connected:false}}function render(data){el('output').textContent=typeof data.answer==='string'?data.answer+'\n\n'+(data.sources?'Sources\n'+JSON.stringify(data.sources,null,2):''):JSON.stringify(data,null,2)}el('connect').addEventListener('click',()=>run('connect',async()=>{token=el('token').value.trim();el('token').value='';const data=await api('status');connected=true;state('agent','Connected · Python controller',true);['knowledge','dashboard'].forEach(name=>{const good=data.services?.[name]?.reachable===true;state(name,good?'Available':'Unavailable',good)});actionButtons.forEach(id=>el(id).disabled=false);el('checked').textContent='Last checked '+new Date().toLocaleTimeString()}));el('disconnect').addEventListener('click',disconnect);el('ask').addEventListener('click',()=>run('ask',async()=>{const question=el('question').value.trim();if(!question)throw new Error('Enter a question.');render(await api('chat',{question}))}));el('search').addEventListener('click',()=>run('search',async()=>{const query=el('query').value.trim();if(!query)throw new Error('Enter search terms.');render(await api('search?q='+encodeURIComponent(query)))}));el('inventory').addEventListener('click',()=>run('inventory',async()=>render(await api('metrics'))));['chat','search','inventory'].forEach(name=>el(name+'-tab').addEventListener('click',()=>{['chat','search','inventory'].forEach(other=>{el(other+'-tab').setAttribute('aria-selected',String(other===name));el(other+'-panel').classList.toggle('hidden',other!==name)});el('output').textContent=''}));window.addEventListener('pagehide',disconnect)})();
</script></body></html>'''
